lab.solution:
from pathlib import Path

path = Path('study_notes.txt')

try:
    text = path.read_text(encoding='utf-8')
except FileNotFoundError:
    print('Study notes were not found yet.')
else:
    print(f'Loaded {len(text)} characters of notes.')
